let theShader;
let sourceGraphics,shaderGraphics;
var boolTrigger;

const ballsCount = 40;
const balls = [];

function preload(){
	theShader = getShader(this._renderer);
}

function setup() {
	createCanvas(windowHeight, windowHeight);
	sourceGraphics= createGraphics(width,height)
	shaderGraphics = createGraphics(width,height,WEBGL)
	sourceGraphics.background(0) 

	for (let i = 0; i < ballsCount; i ++){
		balls.push(new ball());
	}
}

function draw() {
	const dataBalls = [];
	const lifespan = [];
	for (const b of balls) {
		b.update();
		dataBalls.push(b.position.x, b.position.y, b.rad);
		lifespan.push(b.lifespan);
	}
	background(0, 255)
	sourceGraphics.background(0, 255)

	shaderGraphics.shader(theShader)
	theShader.setUniform('u_resolution',[width/windowHeight,height/windowHeight])
	theShader.setUniform('u_time', millis()*0.00003) //SPEEEEEED 0.00003
	theShader.setUniform('u_tex', sourceGraphics)
	theShader.setUniform("balls", dataBalls);
	theShader.setUniform("lifespan", lifespan);
	theShader.setUniform("(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))", (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
	theShader.setUniform("(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))", (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

	shaderGraphics.rect(-width/2,-height/2,width,height)
	blendMode(ADD)
	image(sourceGraphics,0,0)
	image(shaderGraphics,0,0)
